	LogicalOperatorVisitor::Visit(op);

	if (!op.table) {
		this->plan = make_unique<PhysicalDummyScan>();
		return;
	}
	auto scan = make_unique<PhysicalTableScan>(*op.table, *op.table->storage,
	                                           op.column_ids);
	if (plan) {
		throw Exception("Scan has to be the first node of a plan!");
	}
	this->plan = move(scan);
