+		if (child_type < ExpressionType::COMPARE_EQUAL ||
+			child_type > ExpressionType::COMPARE_GREATERTHANOREQUALTO) {
+			throw Exception("ON NOT only supports comparision operators");
+		}
+		// switcheroo the child condition
