idx_t MaxLineSize(string &path) {
	idx_t max_line_size = 0;

	ifstream infile(path);

	string line;
	while (getline(infile, line)) {
		int line_size = line.length();
		if (line_size > max_line_size) {
			max_line_size = line_size;
		}
	}
	infile.close();
	return max_line_size;
}

