+	const UNSIGNED shift = (sizeof(UNSIGNED) - NEEDLE_SIZE) * 8;
+	for(int i = 0; i < NEEDLE_SIZE; i++) {
+		needle_entry   |= UNSIGNED(needle[i])   << UNSIGNED(start - i * 8);
